/**
 * The three light syntax palettes Shiki does not ship.
 *
 * Paseo's Appearance > Syntax theme names a palette family and one daemon serves
 * readers in either scheme, so `index.server.ts` needs a light theme per family.
 * Shiki 4.4.3 ships none for Dracula, Tokyo Night or Nord. Each object below is
 * that theme's own TextMate mapping, converted from its published source with
 * the workbench colours dropped (the plugin never paints a code background) and
 * only `foreground` and `fontStyle` kept per rule, in upstream order. Where a
 * source wrote a hex without `#`, or with an opaque `ff` alpha suffix, the hex
 * was normalized rather than recoloured:
 *
 * - `alucard`: https://github.com/dracula/cursor/raw/refs/heads/main/dev/src/alucard.yml
 *   (Alucard is Dracula's own light half), from its `tokenColors`.
 * - `tokyo-night-light`: https://github.com/tokyo-night/tokyo-night-vscode-theme/raw/refs/heads/master/themes/tokyo-night-light-color-theme.json,
 *   from its `tokenColors`; upstream labels that file `dark`, which it is not.
 * - `polar`: https://github.com/mtyn/polar, from
 *   https://github.com/mtyn/polar/raw/refs/heads/master/polar/vscode/themes/Polar-color-theme.json
 *   `tokenColors`. Unlike the two above this one is unofficial — Polar is a third
 *   party theme, named here after its own source because Nord publishes no light
 *   theme of its own. Polar keeps the dark palette's pastel hues, so some rules
 *   read faint on a light surface (`comment` measures 1.3:1 against white); the
 *   values stay as upstream wrote them.
 *
 * Regenerate by repeating that conversion over the same three files rather than
 * editing rules here: an entry out of order or a recoloured scope is drift
 * nobody asked for, and the tests only prove the six streaming roles still line
 * up (`test/unit/syntax-theme-server.test.ts`).
 */

/** One rule as Shiki reads it; `scope` matches TextMate grammar scopes. */
interface VendoredRule {
  scope: string | string[];
  settings: Record<string, string>;
}

/** A Shiki TextMate theme. `type` only picks Shiki's own fg/bg defaults. */
export interface VendoredTheme {
  name: string;
  type: "light";
  colors: Record<string, string>;
  settings: VendoredRule[];
}

